SELECT a.id, a.customer_id, t.pct_lazada FROM accounts a LEFT OUTER JOIN (SELECT account_id, ROUND((100 * SUM(CASE WHEN merchant = 'Lazada' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_lazada FROM transactions GROUP BY account_id) t ON a.id = t.account_id WHERE t.pct_lazada >= 29 ORDER BY customer_id DESC;
